INSERT INTO public.diagnostic_centres (id, name, area, address, phone, hours, home_collection, notes) VALUES
  ('centre-popular', 'Popular Diagnostic Centre', 'Dhanmondi', 'House 16, Road 2, Dhanmondi, Dhaka 1205', '+880 9613-787801', '7:00 AM – 11:00 PM (Daily)', true, 'High-throughput automated lab with SMS/online report portal and home sample collection across Dhanmondi.'),
  ('centre-islami', 'Islami Bank Hospital', 'Kakrail / Motijheel', '24/B Outer Circular Road, Motijheel, Dhaka 1000', '+880 2-9336421', '7:30 AM – 10:30 PM (Daily)', true, 'Known for affordable reference rates on routine pathology, radiology, and cardiac diagnostics.'),
  ('centre-labaid', 'Labaid Specialized Hospital', 'Dhanmondi', 'House 06, Road 04, Dhanmondi, Dhaka 1205', '+880 1766-662111', '24 Hours Diagnostic Wing', true, 'Dedicated 24/7 imaging, cardiac diagnostics, and priority digital reporting desk.'),
  ('centre-ibnsina', 'Ibn Sina Diagnostic & Imaging', 'Mirpur', 'House 11, Road 1, Block A, Mirpur 10, Dhaka 1216', '+880 9610-010615', '7:30 AM – 11:00 PM (Daily)', true, 'Popular for transparent pricing, digital X-Ray/MRI units, and weekend sample collection.'),
  ('centre-medipath', 'Medipath Diagnostic Complex', 'Matikata', 'Matikata Main Road, Cantonment Area, Dhaka 1206', '+880 1711-002233', '8:00 AM – 10:00 PM (Sat–Thu)', false, 'Neighbourhood diagnostic facility serving Matikata & Mirpur DOHS with fast same-day reporting.'),
  ('centre-amana', 'Amana Hospital', 'Laxmipur', 'Hospital Road, Laxmipur Sadar / Regional Hub', '+880 1722-004455', '7:30 AM – 10:00 PM (Daily)', true, 'Regional multi-unit hospital offering budget-friendly diagnostic packages and endoscopy services.')
