INSERT INTO public.patient_reviews (id, centre_id, user_id, author, rating, comment, created_at, verified_visitor) VALUES
  ('rev-1', 'centre-islami', NULL, 'Mahmudul Hasan', 5, 'Very reasonable diagnostic fees compared to larger private hubs. Got my CBC and ECG report the same afternoon.', '2026-10-12', true),
  ('rev-2', 'centre-popular', NULL, 'Nusrat Jahan', 4, 'Morning rush at Dhanmondi branch can be busy, but online report download worked smoothly without needing a second trip.', '2026-10-19', true),
  ('rev-3', 'centre-ibnsina', NULL, 'Tanvir Ahmed', 5, 'Booked home blood collection for my father in Mirpur. Phlebotomist arrived on time and fees matched the counter list.', '2026-10-25', false),
  ('rev-4', 'centre-labaid', NULL, 'Farhana Yasmin', 4, 'Clean waiting lounge and helpful cardiology technicians for Echocardiogram, though prices are slightly higher.', '2026-11-02', true),
  ('rev-5', 'centre-medipath', NULL, 'Kamrul Islam', 4, 'Convenient for quick routine tests near Matikata with minimal queue time.', '2026-11-06', false),
  ('rev-6', 'centre-amana', NULL, 'Sadia Afrin', 5, 'Affordable health checkup package and polite reception staff.', '2026-11-10', true)
